import{_ as p,o as t,c as a,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const E=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/OUTPUT.md","filePath":"manual-zh/OUTPUT.md","lastUpdated":1785684581000}'),T={name:"manual-zh/OUTPUT.md"};function c(d,e,n,r,s,_){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h3 id="_17-17-output" tabindex="-1">17.17 OUTPUT <a class="header-anchor" href="#_17-17-output" aria-label="Permalink to &quot;17.17 OUTPUT&quot;">​</a></h3><pre><code>OUTPUT MODIFY
       /SELECT TABLES
       /TABLECELLS SELECT = [ class... ]
                   FORMAT = fmt_spec.
</code></pre><blockquote><p><strong>请注意：</strong> 在上面的大纲中，字符 ‘[’ 和 ‘]’ 是字面量。它们必须出现在语法中才能被正确解释。</p></blockquote><p><code>OUTPUT</code> 改变打印结果的表格的外观。特别是，它可用于设置结果显示的格式和精度。</p><p>运行此命令后，默认的表格外观参数将被修改，随后生成的每个新输出表格都会使用新的参数。</p><p>在 <code>/TABLECELLS SELECT =</code> 之后必须出现一个单元格类别列表，用方括号括起来。该列表决定应选择哪些类别的值进行修改。每个类别可以是：</p><p>RESIDUAL</p><p>残差值。默认：<code>F40.2</code>。</p><p>CORRELATION</p><p>相关系数。默认：<code>F40.3</code>。</p><p>PERCENT</p><p>百分比。默认：<code>PCT40.1</code>。</p><p>SIGNIFICANCE</p><p>检验的显著性（p 值）。默认：<code>F40.3</code>。</p><p>COUNT</p><p>计数或权重之和。对于加权数据集，默认值为权重变量的打印格式。对于未加权数据集，默认值为 F40.0。</p><p>对于表格中出现的其他大多数数值，<code>SET FORMAT</code> 可用于指定格式（参见 <a href="./SET#SET-FORMAT">SET FORMAT</a>）。</p><p>fmt_spec 的值必须是有效的输出格式（参见 <a href="./Input-and-Output-Formats">Input and Output Formats</a>）。请注意，并非所有可能的格式对所有类别都有意义。</p>`,18)])])}const l=p(T,[["render",c]]);export{E as __pageData,l as default};
